# -*- coding: utf-8 -*-
"""Embedded publication photos for lot 1205."""
import base64
import io
import json
import shutil
import zipfile
from pathlib import Path

ZIP_B64 = """







"""

def materialize() -> list[Path]:
    work = Path("/tmp/cozy_airbnb_sgphb3_1205")
    if work.exists():
        shutil.rmtree(work)
    work.mkdir(parents=True)
    package = work / "package"
    package.mkdir()
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(ZIP_B64)), "r") as zf:
        zf.extractall(package)
    manifest = json.loads((package / "manifest.json").read_text(encoding="utf-8"))
    names = ["01_exterior.jpeg", "02_pool.jpeg", "03_living.jpeg", "04_bedroom.jpeg", "05_kitchen.jpeg"]
    if list(manifest.get("photos") or []) != names:
        raise RuntimeError(f"Unexpected photo manifest: {manifest.get('photos')}")
    photos = [package / "photos" / name for name in names]
    if any(not p.is_file() for p in photos):
        raise RuntimeError("Embedded publication photos are incomplete")
    return photos
